  HIGH = '상',
  EXTREME = '최상'
}

export enum ProblemType {
  CONCEPT = '개념 확인',
  TYPE = '유형 익히기',
  SKILL = '실력 다지기',
  CREATIVE = '창의 융합/서술형'
}

// Hierarchical Curriculum Data Structure
