  name: string;
  subUnits?: CurriculumUnit[];
}

export interface GeneratedProblem {
  question: string;
  choices?: string[]; // Optional for multiple choice
  answer: string;
  solution: string;
  topic: string; // The specific topic derived
  difficulty: string;
}

