import { GoogleGenAI, Type } from "@google/genai";
import { GeneratedProblem, SelectionState } from "../types";

// Initialize Gemini Client
// IMPORTANT: In a real app, ensure process.env.API_KEY is available.
// For this demo environment, we assume it's injected.
const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key is missing. Please set process.env.API_KEY.");
  }
  return new GoogleGenAI({ apiKey });
};

export const generateMathProblem = async (selection: SelectionState): Promise<GeneratedProblem> => {
  const ai = getClient();

  // Construct the prompt context based on user selection
  const topicPath = `${selection.schoolLevel} ${selection.grade} > ${selection.mainUnit} > ${selection.subUnit} > ${selection.detailUnit}`;

  const prompt = `
    You are an expert Mathematics Teacher in South Korea, specializing in the "2022 Revised National Curriculum" (2022 개정 교육과정).

    Task: Create a mathematics problem based on the following specifications.

    Target Audience/Topic:
    - Curriculum Path: ${topicPath}
    - Difficulty: ${selection.difficulty} (Range: Lower, Middle, High, Highest)
    - Problem Type: ${selection.problemType}

    Requirements:
    1. The problem must be mathematically accurate and suitable for the selected grade level in Korea.
    2. Use LaTeX formatting for all mathematical expressions. Use $ for inline math and $$ for block math.
    3. If the problem is multiple choice, provide 5 choices. If it is short answer (주관식) or descriptive (서술형), leave choices empty.
    4. Provide a detailed step-by-step solution in Korean.
    5. The output MUST be valid JSON.

    Language: Korean (한국어)
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview', // Using Pro for better mathematical reasoning
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            question: {
              type: Type.STRING,
              description: "The main text of the question, including LaTeX."
            },
            choices: {
              type: Type.ARRAY,
              items: { type: Type.STRING },
              description: "Array of 5 options if multiple choice, otherwise empty."
            },
            answer: {
              type: Type.STRING,
              description: "The correct answer value."
            },
            solution: {
              type: Type.STRING,
              description: "Detailed step-by-step explanation."
            },
            topic: {
              type: Type.STRING,
              description: "A concise label of the math concept tested."
            },
            difficulty: {
              type: Type.STRING,
              description: "The difficulty level of this specific problem."
            }
          },
          required: ["question", "answer", "solution", "topic", "difficulty"]
        }
      }
    });

    if (!response.text) {
      throw new Error("No content generated.");
    }

    const data = JSON.parse(response.text) as GeneratedProblem;
    return data;
  } catch (error) {
    console.error("Error generating problem:", error);
    throw error;
  }
};

import React from 'react';
import ReactMarkdown from 'react-markdown';
import remarkMath from 'remark-math';
import rehypeKatex from 'rehype-katex';

interface MarkdownRendererProps {
  content: string;
  className?: string;
}

const MarkdownRenderer: React.FC<MarkdownRendererProps> = ({ content, className }) => {
  return (
    <div className={`prose prose-slate max-w-none prose-p:my-2 prose-headings:my-3 ${className}`}>
      <ReactMarkdown
        remarkPlugins={[remarkMath]}
        rehypePlugins={[rehypeKatex]}
        components={{
          // Override paragraph to avoid hydration errors with some math blocks if necessary,
          // though standard configuration usually works.
          p: ({ node, children, ...props }) => <p className="leading-relaxed text-slate-800" {...props}>{children}</p>
        }}
      >
        {content}
      </ReactMarkdown>
    </div>
  );
};

export default MarkdownRenderer;

import React, { useEffect, useState } from 'react';
import { SelectionState, SchoolLevel, Difficulty, ProblemType, CurriculumUnit } from '../types';
import { MIDDLE_SCHOOL_CURRICULUM, HIGH_SCHOOL_CURRICULUM } from '../constants';
import { BookOpen, GraduationCap, Layers, Zap } from 'lucide-react';

interface SelectionPanelProps {
  selection: SelectionState;
  onChange: (newSelection: SelectionState) => void;
  onGenerate: () => void;
  isLoading: boolean;
}

const SelectionPanel: React.FC<SelectionPanelProps> = ({ selection, onChange, onGenerate, isLoading }) => {
  const [availableMainUnits, setAvailableMainUnits] = useState<CurriculumUnit[]>([]);
  const [availableSubUnits, setAvailableSubUnits] = useState<CurriculumUnit[]>([]);

  // Update Main Units when Level/Grade changes
  useEffect(() => {
    let units: CurriculumUnit[] = [];
    if (selection.schoolLevel === SchoolLevel.MIDDLE) {
      units = MIDDLE_SCHOOL_CURRICULUM[selection.grade] || [];
    } else {
      units = HIGH_SCHOOL_CURRICULUM[selection.grade] || [];
    }
    setAvailableMainUnits(units);

    // Auto-select first main unit if current selection is invalid
    const exists = units.find(u => u.name === selection.mainUnit);
    if (!exists && units.length > 0) {
      handleChange('mainUnit', units[0].name);
    } else if (units.length === 0) {
      handleChange('mainUnit', '');
    }
  }, [selection.schoolLevel, selection.grade]);

  // Update Sub Units when Main Unit changes
  useEffect(() => {
    const main = availableMainUnits.find(u => u.name === selection.mainUnit);
    const subs = main?.subUnits || [];
    setAvailableSubUnits(subs);

    const exists = subs.find(u => u.name === selection.subUnit);
    if (!exists && subs.length > 0) {
      handleChange('subUnit', subs[0].name);
    } else if (subs.length === 0) {
      handleChange('subUnit', '');
    }
  }, [selection.mainUnit, availableMainUnits]);

  const handleChange = (field: keyof SelectionState, value: any) => {
    onChange({ ...selection, [field]: value });
  };

  const getGrades = () => {
    return selection.schoolLevel === SchoolLevel.MIDDLE 
      ? ['1학년', '2학년', '3학년'] 
      : ['공통수학1', '공통수학2', '대수', '미적분I']; // Simplified for 2022 demo
  };

  return (
    <div className="w-full md:w-80 bg-white border-r border-slate-200 h-full flex flex-col">
      <div className="p-6 border-b border-slate-100">
        <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
          <GraduationCap className="text-indigo-600" />
          MathGen AI
        </h1>
        <p className="text-xs text-slate-500 mt-1">2022 개정 교육과정 기반</p>
      </div>

      <div className="flex-1 overflow-y-auto p-6 space-y-6">

        {/* School Level & Grade */}
        <div className="space-y-3">
          <label className="text-sm font-semibold text-slate-700 flex items-center gap-2">
            <BookOpen size={16} /> 학제 및 학년
          </label>
          <div className="grid grid-cols-2 gap-2">
            {(Object.values(SchoolLevel) as string[]).map((level) => (
              <button
                key={level}
                onClick={() => handleChange('schoolLevel', level)}
                className={`px-3 py-2 text-sm rounded-lg transition-colors border ${
                  selection.schoolLevel === level
                    ? 'bg-indigo-50 border-indigo-200 text-indigo-700 font-medium'
                    : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'
                }`}
              >
                {level}
              </button>
            ))}
          </div>
          <select
            value={selection.grade}
            onChange={(e) => handleChange('grade', e.target.value)}
            className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
          >
            {getGrades().map(g => <option key={g} value={g}>{g}</option>)}
          </select>
        </div>

        {/* Units */}
        <div className="space-y-3">
          <label className="text-sm font-semibold text-slate-700 flex items-center gap-2">
            <Layers size={16} /> 단원 선택
          </label>
          <div className="space-y-2">
            <div>
              <span className="text-xs text-slate-500 mb-1 block">대단원</span>
              <select
                value={selection.mainUnit}
                onChange={(e) => handleChange('mainUnit', e.target.value)}
                className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-lg text-sm outline-none focus:border-indigo-500 transition-colors"
              >
                {availableMainUnits.map(u => <option key={u.name} value={u.name}>{u.name}</option>)}
              </select>
            </div>
            <div>
              <span className="text-xs text-slate-500 mb-1 block">중단원</span>
              <select
                value={selection.subUnit}
                onChange={(e) => handleChange('subUnit', e.target.value)}
                className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-lg text-sm outline-none focus:border-indigo-500 transition-colors"
                disabled={availableSubUnits.length === 0}
              >
                {availableSubUnits.map(u => <option key={u.name} value={u.name}>{u.name}</option>)}
              </select>
            </div>
            <div>
              <span className="text-xs text-slate-500 mb-1 block">소단원 (직접 입력 가능)</span>
              <input 
                type="text"
                value={selection.detailUnit}
                onChange={(e) => handleChange('detailUnit', e.target.value)}
                placeholder="예: 나머지정리 활용"
                className="w-full p-2.5 bg-white border border-slate-200 rounded-lg text-sm outline-none focus:ring-2 focus:ring-indigo-500"
              />
            </div>
          </div>
        </div>

        {/* Difficulty & Type */}
        <div className="space-y-3">
          <label className="text-sm font-semibold text-slate-700 flex items-center gap-2">
            <Zap size={16} /> 난이도 및 유형
          </label>
          <div className="grid grid-cols-2 gap-2">
            <select
              value={selection.difficulty}
              onChange={(e) => handleChange('difficulty', e.target.value)}
              className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-lg text-sm outline-none"
            >
              {Object.values(Difficulty).map(d => <option key={d} value={d}>{d}</option>)}
            </select>
            <select
              value={selection.problemType}
              onChange={(e) => handleChange('problemType', e.target.value)}
              className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-lg text-sm outline-none"
            >
              {Object.values(ProblemType).map(t => <option key={t} value={t}>{t}</option>)}
            </select>
          </div>
        </div>
      </div>

      <div className="p-6 border-t border-slate-200 bg-slate-50">
        <button
          onClick={onGenerate}
          disabled={isLoading || !selection.mainUnit}
          className={`w-full py-3.5 rounded-xl text-white font-bold shadow-lg shadow-indigo-200 flex items-center justify-center gap-2 transition-all ${
            isLoading || !selection.mainUnit
              ? 'bg-indigo-300 cursor-not-allowed'
              : 'bg-indigo-600 hover:bg-indigo-700 hover:shadow-indigo-300 active:scale-95'
          }`}
        >
          {isLoading ? (
            <>
              <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
              생성 중...
            </>
          ) : (
            <>
              <Zap size={20} fill="currentColor" />
              문제 생성하기
            </>
          )}
        </button>
      </div>
    </div>
  );
};

export default SelectionPanel;

import React, { useState } from 'react';
import { GeneratedProblem } from '../types';
import MarkdownRenderer from './MarkdownRenderer';
import { Eye, EyeOff, CheckCircle, HelpCircle, FileText } from 'lucide-react';

interface ProblemDisplayProps {
  problem: GeneratedProblem | null;
  isLoading: boolean;
}

const ProblemDisplay: React.FC<ProblemDisplayProps> = ({ problem, isLoading }) => {
  const [showSolution, setShowSolution] = useState(false);

  // Reset show solution when problem changes
  React.useEffect(() => {
    setShowSolution(false);
  }, [problem]);

  if (isLoading) {
    return (
      <div className="flex-1 flex flex-col items-center justify-center p-12 text-center h-full">
        <div className="w-16 h-16 mb-6 rounded-full border-4 border-indigo-100 border-t-indigo-600 animate-spin" />
        <h3 className="text-xl font-bold text-slate-800 mb-2">AI 선생님이 문제를 만들고 있어요</h3>
        <p className="text-slate-500 max-w-sm">
          선택하신 단원과 난이도를 분석하여 최적의 문제를 생성 중입니다. 잠시만 기다려주세요.
        </p>
      </div>
    );
  }

  if (!problem) {
    return (
      <div className="flex-1 flex flex-col items-center justify-center p-12 text-center bg-slate-50/50 h-full">
        <div className="w-20 h-20 bg-indigo-50 text-indigo-200 rounded-3xl flex items-center justify-center mb-6">
          <FileText size={40} />
        </div>
        <h3 className="text-xl font-bold text-slate-800 mb-2">문제를 생성해보세요</h3>
        <p className="text-slate-500 max-w-sm">
          왼쪽 패널에서 학년, 단원, 난이도를 선택하고 '문제 생성하기' 버튼을 눌러주세요.
        </p>
      </div>
    );
  }

  return (
    <div className="flex-1 overflow-y-auto bg-slate-100/50 p-4 md:p-8">
      <div className="max-w-4xl mx-auto space-y-6">

        {/* Header Tags */}
        <div className="flex flex-wrap items-center gap-2">
          <span className="bg-indigo-100 text-indigo-700 px-3 py-1 rounded-full text-xs font-semibold tracking-wide">
            {problem.topic}
          </span>
          <span className="bg-slate-200 text-slate-700 px-3 py-1 rounded-full text-xs font-semibold">
            난이도: {problem.difficulty}
          </span>
        </div>

        {/* Question Card */}
        <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
          <div className="bg-slate-50 px-6 py-4 border-b border-slate-100 flex items-center gap-2">
            <span className="flex items-center justify-center w-8 h-8 rounded-lg bg-indigo-600 text-white font-bold text-lg">Q</span>
            <span className="font-semibold text-slate-700">문제</span>
          </div>
          <div className="p-6 md:p-8">
            <MarkdownRenderer content={problem.question} className="text-lg md:text-xl text-slate-800" />

            {/* Choices if available */}
            {problem.choices && problem.choices.length > 0 && (
              <div className="mt-8 grid gap-3">
                {problem.choices.map((choice, idx) => (
                  <div key={idx} className="flex items-start gap-3 group">
                    <span className="flex-shrink-0 w-6 h-6 rounded-full border border-slate-300 text-slate-500 text-sm flex items-center justify-center mt-1 group-hover:border-indigo-400 group-hover:text-indigo-600 transition-colors">
                      {idx + 1}
                    </span>
                    <MarkdownRenderer content={choice} className="text-base text-slate-700" />
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>

        {/* Controls */}
        <div className="flex justify-end">
          <button
            onClick={() => setShowSolution(!showSolution)}
            className="flex items-center gap-2 px-5 py-2.5 rounded-lg bg-white border border-slate-200 text-slate-700 hover:bg-slate-50 hover:border-slate-300 transition-all shadow-sm text-sm font-medium"
          >
            {showSolution ? <EyeOff size={18} /> : <Eye size={18} />}
            {showSolution ? '정답 및 해설 숨기기' : '정답 및 해설 보기'}
          </button>
        </div>

        {/* Answer & Solution Card */}
        {showSolution && (
          <div className="animate-fade-in-up space-y-6">

            {/* Answer */}
            <div className="bg-green-50 rounded-xl border border-green-100 p-6 flex items-start gap-4">
              <CheckCircle className="text-green-600 mt-1 flex-shrink-0" size={24} />
              <div>
                <h4 className="text-green-800 font-bold mb-1">정답</h4>
                <MarkdownRenderer content={problem.answer} className="text-lg text-green-900 font-medium" />
              </div>
            </div>

            {/* Detailed Solution */}
            <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
              <div className="bg-slate-50 px-6 py-4 border-b border-slate-100 flex items-center gap-2">
                <HelpCircle className="text-slate-500" size={20} />
                <span className="font-semibold text-slate-700">상세 풀이</span>
              </div>
              <div className="p-6 md:p-8 bg-white">
                 <MarkdownRenderer content={problem.solution} className="text-base text-slate-700 leading-relaxed" />
              </div>
            </div>
          </div>
        )}

      </div>
    </div>
  );
};

export default ProblemDisplay;

import React, { useState } from 'react';
import SelectionPanel from './components/SelectionPanel';
import ProblemDisplay from './components/ProblemDisplay';
import { generateMathProblem } from './services/geminiService';
import { SelectionState, GeneratedProblem, SchoolLevel, Difficulty, ProblemType } from './types';

// Default initial state
const INITIAL_SELECTION: SelectionState = {
  schoolLevel: SchoolLevel.HIGH,
  grade: '공통수학1',
  mainUnit: '다항식',
  subUnit: '다항식의 연산',
  detailUnit: '',
  difficulty: Difficulty.MEDIUM,
  problemType: ProblemType.TYPE
};

const App: React.FC = () => {
  const [selection, setSelection] = useState<SelectionState>(INITIAL_SELECTION);
  const [problem, setProblem] = useState<GeneratedProblem | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleGenerate = async () => {
    setIsLoading(true);
    setError(null);
    try {
      const generated = await generateMathProblem(selection);
      setProblem(generated);
    } catch (err: any) {
      console.error(err);
      setError("문제를 생성하는 도중 오류가 발생했습니다. 잠시 후 다시 시도해주세요.");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex h-screen w-full bg-slate-100 font-sans text-slate-900">
      {/* Mobile-first layout: Sidebar acts as drawer on mobile (omitted for brevity, assuming desktop/tablet split for now) */}
      <div className="flex w-full h-full overflow-hidden">

        {/* Left Panel: Settings */}
        <SelectionPanel 
          selection={selection} 
          onChange={setSelection}
          onGenerate={handleGenerate}
          isLoading={isLoading}
        />

        {/* Right Panel: Display */}
        <div className="flex-1 flex flex-col h-full relative">
          {error && (
            <div className="absolute top-4 left-1/2 transform -translate-x-1/2 bg-red-100 border border-red-200 text-red-700 px-4 py-2 rounded-lg shadow-lg z-50 flex items-center gap-2">
              <span className="font-bold">오류!</span> {error}
            </div>
          )}

          <ProblemDisplay problem={problem} isLoading={isLoading} />
        </div>
      </div>
    </div>
  );
};

export default App;

