import { GoogleGenAI, Type } from "@google/genai";
import { GeneratedProblem, SelectionState } from "../types";

// Initialize Gemini Client
const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key is missing. Please set process.env.API_KEY.");
  }
  return new GoogleGenAI({ apiKey });
};

export const generateMathProblem = async (selection: SelectionState): Promise<GeneratedProblem> => {
  const ai = getClient();

  // Construct the prompt context based on user selection
  const topicPath = `${selection.schoolLevel} ${selection.grade} > ${selection.mainUnit} > ${selection.subUnit} > ${selection.detailUnit}`;

  const prompt = `
    You are an expert Mathematics Teacher in South Korea, specializing in the "2022 Revised National Curriculum" (2022 개정 교육과정).

    Task: Create a mathematics problem based on the following specifications.

    Target Audience/Topic:
    - Curriculum Path: ${topicPath}
    - Difficulty: ${selection.difficulty} (Range: Lower, Middle, High, Highest)
    - Problem Type: ${selection.problemType}

    Requirements:
    1. The problem must be mathematically accurate and suitable for the selected grade level in Korea.
    2. [Text Formatting]
       - Use LaTeX formatting for all mathematical expressions. Use $ for inline math and $$ for block math.
       - AVOID complex LaTeX table environments (like 'tabular', 'multicolumn') inside the "question" text as they cause rendering errors.
       - For simple tables, use standard Markdown table syntax.
    3. [Problem Structure]
       - If the problem is multiple choice, provide 5 choices.
       - If it is short answer (주관식) or descriptive (서술형), leave "choices" empty.
    4. [Visuals & Diagrams - IMPORTANT]
       - If the problem involves **Geometry** (shapes, angles), **Graphs** (functions), or **Complex Statistics** (like Stem-and-Leaf plots, Histograms) that are hard to represent with text:
         - Generate a valid, high-quality **SVG string** in the "diagramSVG" field.
         - The SVG must be self-contained with a proper 'viewBox'.
         - Use black strokes (stroke="black") and transparent or white background.
         - Ensure text inside SVG is legible (use Hangul if necessary).
       - If no visual is needed, set "diagramSVG" to null.
    5. Provide a detailed step-by-step solution in Korean.
    6. The output MUST be valid JSON.

    Language: Korean (한국어)
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview', // Using Pro for better mathematical reasoning and code generation
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            question: {
              type: Type.STRING,
              description: "The main text of the question. Use Markdown for text and LaTeX ($...$) for math."
            },
            choices: {
              type: Type.ARRAY,
              items: { type: Type.STRING },
              description: "Array of 5 options if multiple choice, otherwise empty."
            },
            answer: {
              type: Type.STRING,
              description: "The correct answer value."
            },
            solution: {
              type: Type.STRING,
              description: "Detailed step-by-step explanation."
            },
            topic: {
              type: Type.STRING,
              description: "A concise label of the math concept tested."
            },
            difficulty: {
              type: Type.STRING,
              description: "The difficulty level of this specific problem."
            },
            diagramSVG: {
              type: Type.STRING,
              description: "A valid SVG code string for the diagram/graph/chart. Null if not needed.",
              nullable: true
            }
          },
          required: ["question", "answer", "solution", "topic", "difficulty"]
        }
      }
    });

    if (!response.text) {
      throw new Error("No content generated.");
    }

    // Robust JSON cleaning: remove markdown code blocks if present
    let jsonString = response.text.trim();
    if (jsonString.startsWith('```json')) {
        jsonString = jsonString.replace(/^```json\s*/, '').replace(/\s*```$/, '');
    } else if (jsonString.startsWith('```')) {
        jsonString = jsonString.replace(/^```\s*/, '').replace(/\s*```$/, '');
    }

    const data = JSON.parse(jsonString) as GeneratedProblem;
    return data;
  } catch (error) {
    console.error("Error generating problem:", error);
    throw error;
  }
};

import React, { useState } from 'react';
import { GeneratedProblem } from '../types';
import MarkdownRenderer from './MarkdownRenderer';
import { Eye, EyeOff, CheckCircle, HelpCircle, FileText, Image as ImageIcon } from 'lucide-react';

interface ProblemDisplayProps {
