          <div className="p-6 md:p-8">
            <MarkdownRenderer content={problem.question} className="text-lg md:text-xl text-slate-800" />

            {/* Visual Diagram (SVG) */}
            {problem.diagramSVG && (
              <div className="my-8 flex justify-center">
                <div className="relative group">
                  <div 
                    className="max-w-full overflow-hidden rounded-lg border border-slate-100 bg-white p-6 shadow-sm"
                    dangerouslySetInnerHTML={{ __html: problem.diagramSVG }} 
                  />
                  <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity bg-slate-100 text-slate-400 p-1 rounded">
                    <ImageIcon size={16} />
