import { GoogleGenAI, Type } from "@google/genai";
import { GeneratedProblem, SelectionState } from "../types";

// Initialize Gemini Client
const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key is missing. Please set process.env.API_KEY.");
  }
  return new GoogleGenAI({ apiKey });
};

export const generateMathProblem = async (selection: SelectionState): Promise<GeneratedProblem> => {
  const ai = getClient();

  // Construct the prompt context based on user selection
  const topicPath = `${selection.schoolLevel} ${selection.grade} > ${selection.mainUnit} > ${selection.subUnit} > ${selection.detailUnit}`;

  const prompt = `
    You are an expert Mathematics Teacher in South Korea, specializing in the "2022 Revised National Curriculum" (2022 개정 교육과정).

    Task: Create a mathematics problem based on the following specifications.

    Target Audience/Topic:
    - Curriculum Path: ${topicPath}
    - Difficulty: ${selection.difficulty} (Range: Lower, Middle, High, Highest)
    - Problem Type: ${selection.problemType}

    Requirements:
    1. The problem must be mathematically accurate and suitable for the selected grade level in Korea.
    2. [Text Formatting & LaTeX - CRITICAL]
       - Use LaTeX formatting for **ALL** mathematical expressions, numbers, variables, and formulas.
       - **Inline Math**: Wrap in single dollar signs, e.g., $x^2 + 2x + 1$.
       - **Block Math**: Wrap in double dollar signs, e.g., $$ \\frac{-b \\pm \\sqrt{b^2 - 4ac}}{2a} $$.
       - **CHOICES (보기)**: You MUST wrap the mathematical content of each choice in $ symbols. 
         - Incorrect: "x^2 + x" 
         - Correct: "$x^2 + x$"
         - Incorrect: "-5"
         - Correct: "$-5$"
       - AVOID complex LaTeX table environments inside the "question" text. Use standard Markdown tables.
    3. [Problem Structure]
       - If the problem is multiple choice, provide 5 choices.
       - If it is short answer (주관식) or descriptive (서술형), leave "choices" empty.
    4. [Visuals & Diagrams]
       - If the problem involves **Geometry**, **Graphs**, or **Statistics** (Stem & Leaf, etc.):
         - Generate a valid, high-quality **SVG string** in the "diagramSVG" field.
         - Self-contained SVG with 'viewBox', black strokes, transparent background.
       - Otherwise, set "diagramSVG" to null.
    5. Provide a detailed step-by-step solution in Korean.
    6. The output MUST be valid JSON.

    Language: Korean (한국어)
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview', // Using Pro for better mathematical reasoning and code generation
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            question: {
              type: Type.STRING,
              description: "The main text. Use Markdown. WRAP MATH IN $...$."
            },
            choices: {
              type: Type.ARRAY,
              items: { type: Type.STRING },
              description: "Array of 5 options. MUST WRAP MATH IN $...$."
            },
            answer: {
              type: Type.STRING,
              description: "The correct answer value."
            },
            solution: {
              type: Type.STRING,
              description: "Detailed solution."
            },
            topic: {
              type: Type.STRING,
              description: "Topic label."
            },
            difficulty: {
              type: Type.STRING,
              description: "Difficulty level."
            },
            diagramSVG: {
              type: Type.STRING,
              description: "SVG code or null.",
              nullable: true
            }
          },
          required: ["question", "answer", "solution", "topic", "difficulty"]
        }
      }
    });

    if (!response.text) {
      throw new Error("No content generated.");
    }

    // Robust JSON cleaning: remove markdown code blocks if present
    let jsonString = response.text.trim();
    if (jsonString.startsWith('```json')) {
        jsonString = jsonString.replace(/^```json\s*/, '').replace(/\s*```$/, '');
    } else if (jsonString.startsWith('```')) {
        jsonString = jsonString.replace(/^```\s*/, '').replace(/\s*```$/, '');
    }

    const data = JSON.parse(jsonString) as GeneratedProblem;
    return data;
  } catch (error) {
    console.error("Error generating problem:", error);
    throw error;
  }
};

import React, { useState } from 'react';
import SelectionPanel from './components/SelectionPanel';
import ProblemDisplay from './components/ProblemDisplay';
import { generateMathProblem } from './services/geminiService';
import { SelectionState, GeneratedProblem, SchoolLevel, Difficulty, ProblemType } from './types';

// Default initial state matching new 2022 curriculum constants
const INITIAL_SELECTION: SelectionState = {
  schoolLevel: SchoolLevel.HIGH,
  grade: '공통수학1',
  mainUnit: '다항식',
  subUnit: '다항식의 연산',
  detailUnit: '다항식의 덧셈과 뺄셈',
  difficulty: Difficulty.MEDIUM,
  problemType: ProblemType.TYPE
};

const App: React.FC = () => {
  const [selection, setSelection] = useState<SelectionState>(INITIAL_SELECTION);
  const [problem, setProblem] = useState<GeneratedProblem | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleGenerate = async () => {
    setIsLoading(true);
    setError(null);
    try {
      const generated = await generateMathProblem(selection);
      setProblem(generated);
    } catch (err: any) {
      console.error(err);
      setError("문제를 생성하는 도중 오류가 발생했습니다. 잠시 후 다시 시도해주세요.");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex h-screen w-full bg-slate-100 font-sans text-slate-900 print:h-auto print:bg-white print:block">
      {/* Container - flex on screen, block on print */}
      <div className="flex w-full h-full overflow-hidden print:h-auto print:overflow-visible print:block">

        {/* Left Panel: Settings - Hidden on Print */}
        <SelectionPanel 
          selection={selection} 
          onChange={setSelection}
          onGenerate={handleGenerate}
          isLoading={isLoading}
        />

        {/* Right Panel: Display - Full width on Print */}
        <div className="flex-1 flex flex-col h-full relative print:h-auto print:w-full print:block">
          {error && (
            <div className="absolute top-4 left-1/2 transform -translate-x-1/2 bg-red-100 border border-red-200 text-red-700 px-4 py-2 rounded-lg shadow-lg z-50 flex items-center gap-2 print:hidden">
              <span className="font-bold">오류!</span> {error}
            </div>
          )}

          <ProblemDisplay problem={problem} isLoading={isLoading} />
        </div>
      </div>
    </div>
  );
};

export default App;

import React, { useEffect, useState } from 'react';
import { SelectionState, SchoolLevel, Difficulty, ProblemType, CurriculumUnit } from '../types';
import { MIDDLE_SCHOOL_CURRICULUM, HIGH_SCHOOL_CURRICULUM } from '../constants';
import { BookOpen, GraduationCap, Layers, Zap } from 'lucide-react';

interface SelectionPanelProps {
  selection: SelectionState;
  onChange: (newSelection: SelectionState) => void;
  onGenerate: () => void;
  isLoading: boolean;
}

const SelectionPanel: React.FC<SelectionPanelProps> = ({ selection, onChange, onGenerate, isLoading }) => {
  const [availableMainUnits, setAvailableMainUnits] = useState<CurriculumUnit[]>([]);
  const [availableSubUnits, setAvailableSubUnits] = useState<CurriculumUnit[]>([]);
  const [availableDetailUnits, setAvailableDetailUnits] = useState<CurriculumUnit[]>([]);

  // Update Main Units when Level/Grade changes
  useEffect(() => {
    let units: CurriculumUnit[] = [];
    if (selection.schoolLevel === SchoolLevel.MIDDLE) {
      units = MIDDLE_SCHOOL_CURRICULUM[selection.grade] || [];
    } else {
      units = HIGH_SCHOOL_CURRICULUM[selection.grade] || [];
    }
    setAvailableMainUnits(units);

    // Reset downward selections safely
    if (units.length > 0) {
      handleChange('mainUnit', units[0].name);
    } else {
      handleChange('mainUnit', '');
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selection.schoolLevel, selection.grade]);

  // Update Sub Units when Main Unit changes
  useEffect(() => {
    const main = availableMainUnits.find(u => u.name === selection.mainUnit);
    const subs = main?.subUnits || [];
    setAvailableSubUnits(subs);

    if (subs.length > 0) {
      handleChange('subUnit', subs[0].name);
    } else {
      handleChange('subUnit', '');
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selection.mainUnit, availableMainUnits]);

  // Update Detail Units when Sub Unit changes
  useEffect(() => {
    const sub = availableSubUnits.find(u => u.name === selection.subUnit);
    const details = sub?.subUnits || [];
    setAvailableDetailUnits(details);

    if (details.length > 0) {
      handleChange('detailUnit', details[0].name);
    } else {
      handleChange('detailUnit', '');
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selection.subUnit, availableSubUnits]);

  const handleChange = (field: keyof SelectionState, value: any) => {
    if (selection[field] !== value) {
      onChange({ ...selection, [field]: value });
    }
  };

  const getGrades = () => {
    return selection.schoolLevel === SchoolLevel.MIDDLE 
      ? ['1학년 1학기', '1학년 2학기', '2학년 1학기', '2학년 2학기', '3학년 1학기', '3학년 2학기'] 
      : ['공통수학1', '공통수학2', '대수', '미적분I', '확률과 통계', '미적분II', '기하'];
  };

  return (
    <div className="w-full md:w-80 bg-white border-r border-slate-200 h-full flex flex-col print:hidden">
      <div className="p-6 border-b border-slate-100">
        <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
          <GraduationCap className="text-indigo-600" />
          MathGen AI
        </h1>
        <p className="text-xs text-slate-500 mt-1">2022 개정 교육과정 기반</p>
      </div>

      <div className="flex-1 overflow-y-auto p-6 space-y-6">

        {/* School Level & Grade */}
        <div className="space-y-3">
          <label className="text-sm font-semibold text-slate-700 flex items-center gap-2">
            <BookOpen size={16} /> 학제 및 학년
          </label>
          <div className="grid grid-cols-2 gap-2">
            {(Object.values(SchoolLevel) as string[]).map((level) => (
              <button
                key={level}
                onClick={() => handleChange('schoolLevel', level)}
                className={`px-3 py-2 text-sm rounded-lg transition-colors border ${
                  selection.schoolLevel === level
                    ? 'bg-indigo-50 border-indigo-200 text-indigo-700 font-medium'
                    : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'
                }`}
              >
                {level}
              </button>
            ))}
          </div>
          <select
            value={selection.grade}
            onChange={(e) => handleChange('grade', e.target.value)}
            className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
          >
            {getGrades().map(g => <option key={g} value={g}>{g}</option>)}
          </select>
        </div>

        {/* Units */}
        <div className="space-y-3">
          <label className="text-sm font-semibold text-slate-700 flex items-center gap-2">
            <Layers size={16} /> 단원 선택
          </label>
          <div className="space-y-2">
            <div>
              <span className="text-xs text-slate-500 mb-1 block">대단원</span>
              <select
                value={selection.mainUnit}
                onChange={(e) => handleChange('mainUnit', e.target.value)}
                className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-lg text-sm outline-none focus:border-indigo-500 transition-colors"
              >
                {availableMainUnits.length > 0 ? (
                  availableMainUnits.map(u => <option key={u.name} value={u.name}>{u.name}</option>)
                ) : (
                  <option value="">단원 없음</option>
                )}
              </select>
            </div>
            <div>
              <span className="text-xs text-slate-500 mb-1 block">중단원</span>
              <select
                value={selection.subUnit}
                onChange={(e) => handleChange('subUnit', e.target.value)}
                className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-lg text-sm outline-none focus:border-indigo-500 transition-colors"
                disabled={availableSubUnits.length === 0}
              >
                {availableSubUnits.length > 0 ? (
                   availableSubUnits.map(u => <option key={u.name} value={u.name}>{u.name}</option>)
                ) : (
                  <option value="">중단원 없음</option>
                )}
              </select>
            </div>
            <div>
              <span className="text-xs text-slate-500 mb-1 block">소단원</span>
               {availableDetailUnits.length > 0 ? (
                <select 
                  value={selection.detailUnit}
                  onChange={(e) => handleChange('detailUnit', e.target.value)}
                  className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-lg text-sm outline-none focus:ring-2 focus:ring-indigo-500"
                >
                  {availableDetailUnits.map(u => <option key={u.name} value={u.name}>{u.name}</option>)}
                </select>
              ) : (
                <input 
                  type="text"
                  value={selection.detailUnit}
                  onChange={(e) => handleChange('detailUnit', e.target.value)}
                  placeholder="직접 입력"
                  className="w-full p-2.5 bg-white border border-slate-200 rounded-lg text-sm outline-none focus:ring-2 focus:ring-indigo-500"
                />
              )}
            </div>
          </div>
        </div>

        {/* Difficulty & Type */}
        <div className="space-y-3">
          <label className="text-sm font-semibold text-slate-700 flex items-center gap-2">
            <Zap size={16} /> 난이도 및 유형
          </label>
          <div className="grid grid-cols-2 gap-2">
            <select
              value={selection.difficulty}
              onChange={(e) => handleChange('difficulty', e.target.value)}
              className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-lg text-sm outline-none"
            >
              {Object.values(Difficulty).map(d => <option key={d} value={d}>{d}</option>)}
            </select>
            <select
              value={selection.problemType}
              onChange={(e) => handleChange('problemType', e.target.value)}
              className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-lg text-sm outline-none"
            >
              {Object.values(ProblemType).map(t => <option key={t} value={t}>{t}</option>)}
            </select>
          </div>
        </div>
      </div>

      <div className="p-6 border-t border-slate-200 bg-slate-50">
        <button
          onClick={onGenerate}
          disabled={isLoading || !selection.mainUnit}
          className={`w-full py-3.5 rounded-xl text-white font-bold shadow-lg shadow-indigo-200 flex items-center justify-center gap-2 transition-all ${
            isLoading || !selection.mainUnit
              ? 'bg-indigo-300 cursor-not-allowed'
              : 'bg-indigo-600 hover:bg-indigo-700 hover:shadow-indigo-300 active:scale-95'
          }`}
        >
          {isLoading ? (
            <>
              <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
              생성 중...
            </>
          ) : (
            <>
              <Zap size={20} fill="currentColor" />
              문제 생성하기
            </>
          )}
        </button>
      </div>
    </div>
  );
};

export default SelectionPanel;

import React, { useState } from 'react';
import { GeneratedProblem } from '../types';
import MarkdownRenderer from './MarkdownRenderer';
import { Eye, EyeOff, CheckCircle, HelpCircle, FileText, Image as ImageIcon, Printer } from 'lucide-react';

interface ProblemDisplayProps {
  problem: GeneratedProblem | null;
  isLoading: boolean;
}

const ProblemDisplay: React.FC<ProblemDisplayProps> = ({ problem, isLoading }) => {
  const [showSolution, setShowSolution] = useState(false);

  // Reset show solution when problem changes
  React.useEffect(() => {
    setShowSolution(false);
  }, [problem]);

  // Handler for printing
  const handlePrint = (mode: 'problem' | 'solution') => {
    // Determine visibility based on mode
    if (mode === 'problem') {
      setShowSolution(false);
    } else {
      setShowSolution(true);
    }
    // Timeout to allow state update and re-render before printing
    setTimeout(() => {
      window.print();
    }, 100);
  };

  if (isLoading) {
    return (
      <div className="flex-1 flex flex-col items-center justify-center p-12 text-center h-full">
        <div className="w-16 h-16 mb-6 rounded-full border-4 border-indigo-100 border-t-indigo-600 animate-spin" />
        <h3 className="text-xl font-bold text-slate-800 mb-2">AI 선생님이 문제를 만들고 있어요</h3>
        <p className="text-slate-500 max-w-sm">
          선택하신 단원과 난이도를 분석하여 최적의 문제를 생성 중입니다. 잠시만 기다려주세요.
        </p>
      </div>
    );
  }

  if (!problem) {
    return (
      <div className="flex-1 flex flex-col items-center justify-center p-12 text-center bg-slate-50/50 h-full">
        <div className="w-20 h-20 bg-indigo-50 text-indigo-200 rounded-3xl flex items-center justify-center mb-6">
          <FileText size={40} />
        </div>
        <h3 className="text-xl font-bold text-slate-800 mb-2">문제를 생성해보세요</h3>
        <p className="text-slate-500 max-w-sm">
          왼쪽 패널에서 학년, 단원, 난이도를 선택하고 '문제 생성하기' 버튼을 눌러주세요.
        </p>
      </div>
    );
  }

  return (
    <div className="flex-1 overflow-y-auto bg-slate-100/50 p-4 md:p-8 print:p-0 print:bg-white print:overflow-visible">
      <div className="max-w-4xl mx-auto space-y-6 print:max-w-none print:space-y-4">

        {/* Actions Bar - Hidden on Print */}
        <div className="flex justify-between items-center print:hidden">
            <div className="flex items-center gap-2">
                <span className="bg-indigo-100 text-indigo-700 px-3 py-1 rounded-full text-xs font-semibold tracking-wide">
                    {problem.topic}
                </span>
                <span className="bg-slate-200 text-slate-700 px-3 py-1 rounded-full text-xs font-semibold">
                    난이도: {problem.difficulty}
                </span>
            </div>
            <div className="flex gap-2">
                <button
                    onClick={() => handlePrint('problem')}
                    className="flex items-center gap-2 px-3 py-2 rounded-lg bg-white border border-slate-200 text-slate-600 hover:bg-slate-50 hover:text-indigo-600 transition-colors text-sm font-medium shadow-sm"
                    title="문제지만 인쇄합니다 (정답 제외)"
                >
                    <Printer size={16} />
                    문제지 인쇄
                </button>
                <button
                    onClick={() => handlePrint('solution')}
                    className="flex items-center gap-2 px-3 py-2 rounded-lg bg-white border border-slate-200 text-slate-600 hover:bg-slate-50 hover:text-indigo-600 transition-colors text-sm font-medium shadow-sm"
                    title="문제와 해설을 함께 인쇄합니다"
                >
                    <FileText size={16} />
                    해설지 인쇄
                </button>
            </div>
        </div>

        {/* Print Only Header */}
        <div className="hidden print:block border-b-2 border-slate-800 pb-2 mb-6">
            <div className="flex justify-between items-end">
                <h1 className="text-2xl font-bold text-slate-900">MathGen AI 문제지</h1>
                <div className="text-sm text-slate-600">
                    {problem.topic} | 난이도: {problem.difficulty}
                </div>
            </div>
        </div>

        {/* Question Card */}
        <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden print:shadow-none print:border-none print:rounded-none">
          <div className="bg-slate-50 px-6 py-4 border-b border-slate-100 flex items-center gap-2 print:bg-transparent print:border-b print:border-slate-300 print:px-0 print:py-2">
            <span className="flex items-center justify-center w-8 h-8 rounded-lg bg-indigo-600 text-white font-bold text-lg print:bg-black print:text-white print:w-6 print:h-6 print:text-sm print:rounded-md">Q</span>
            <span className="font-semibold text-slate-700 print:text-black">문제</span>
          </div>
          <div className="p-6 md:p-8 print:px-0 print:py-4">
            <MarkdownRenderer content={problem.question} className="text-lg md:text-xl text-slate-800 print:text-black" />

            {/* Visual Diagram (SVG) */}
            {problem.diagramSVG && (
              <div className="my-8 flex justify-center print:my-4">
                <div className="relative group">
                  <div 
                    className="max-w-full overflow-hidden rounded-lg border border-slate-100 bg-white p-6 shadow-sm print:shadow-none print:border-none print:p-0"
                    dangerouslySetInnerHTML={{ __html: problem.diagramSVG }} 
                  />
                </div>
              </div>
            )}

            {/* Choices if available */}
            {problem.choices && problem.choices.length > 0 && (
              <div className="mt-8 grid gap-4 print:mt-4 print:gap-2">
                {problem.choices.map((choice, idx) => (
                  <div key={idx} className="flex items-start gap-3 group print:break-inside-avoid">
                    <span className="flex-shrink-0 w-8 h-8 rounded-full border border-slate-300 text-slate-600 text-base font-medium flex items-center justify-center bg-white print:border-black print:text-black print:w-6 print:h-6 print:text-sm">
                      {idx + 1}
                    </span>
                    <div className="flex-1 pt-0.5">
                      <MarkdownRenderer content={choice} className="text-lg text-slate-800 [&_p]:my-0 print:text-black print:text-base" />
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>

        {/* Controls - Hidden on Print */}
        <div className="flex justify-end print:hidden">
          <button
            onClick={() => setShowSolution(!showSolution)}
            className="flex items-center gap-2 px-5 py-2.5 rounded-lg bg-white border border-slate-200 text-slate-700 hover:bg-slate-50 hover:border-slate-300 transition-all shadow-sm text-sm font-medium"
          >
            {showSolution ? <EyeOff size={18} /> : <Eye size={18} />}
            {showSolution ? '정답 및 해설 숨기기' : '정답 및 해설 확인'}
          </button>
        </div>

        {/* Answer & Solution Card */}
        {showSolution && (
          <div className="animate-fade-in-up space-y-6 print:space-y-4 print:mt-8">

            {/* Print Only Solution Header */}
            <div className="hidden print:block border-b border-slate-300 pb-1 mt-8 mb-4">
                <h2 className="text-xl font-bold text-slate-900">해설지</h2>
            </div>

            {/* Answer */}
            <div className="bg-green-50 rounded-xl border border-green-100 p-6 flex items-start gap-4 print:bg-transparent print:border-none print:p-0 print:block">
              <div className="flex items-center gap-2 mb-2 print:mb-1">
                <CheckCircle className="text-green-600 flex-shrink-0 print:text-black" size={24} />
                <h4 className="text-green-800 font-bold print:text-black">정답</h4>
              </div>
              <div className="print:pl-8">
                <MarkdownRenderer content={problem.answer} className="text-lg text-green-900 font-medium print:text-black" />
              </div>
            </div>

            {/* Detailed Solution */}
            <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden print:shadow-none print:border-none print:rounded-none print:break-inside-avoid">
              <div className="bg-slate-50 px-6 py-4 border-b border-slate-100 flex items-center gap-2 print:hidden">
                <HelpCircle className="text-slate-500" size={20} />
                <span className="font-semibold text-slate-700">상세 풀이</span>
              </div>
              <div className="hidden print:flex items-center gap-2 mb-2">
                 <span className="font-bold text-black border-b border-black">상세 풀이</span>
              </div>
              <div className="p-6 md:p-8 bg-white print:p-0 print:pl-2">
                 <MarkdownRenderer content={problem.solution} className="text-base text-slate-700 leading-relaxed print:text-black print:text-sm" />
              </div>
            </div>
          </div>
        )}

      </div>
    </div>
  );
};

export default ProblemDisplay;

export enum SchoolLevel {
  MIDDLE = '중학교',
  HIGH = '고등학교'
}

export enum Difficulty {
  LOW = '하',
  MEDIUM = '중',
  HIGH = '상',
  EXTREME = '최상'
}

export enum ProblemType {
  CONCEPT = '개념 확인',
  TYPE = '유형 익히기',
  SKILL = '실력 다지기',
  CREATIVE = '창의 융합'
}

export enum AnswerType {
  MULTIPLE_CHOICE = '객관식 (5지선다)',
  SUBJECTIVE = '주관식/서술형'
}

// Hierarchical Curriculum Data Structure
export interface CurriculumUnit {
  name: string;
  subUnits?: CurriculumUnit[];
}

export interface GeneratedProblem {
  question: string;
  choices?: string[]; // Optional for multiple choice
  answer: string;
  solution: string;
  topic: string; // The specific topic derived
  difficulty: string;
  diagramSVG?: string | null; // Optional SVG code for geometry/graphs/tables
}

export interface SelectionState {
  schoolLevel: SchoolLevel;
  grade: string;
  mainUnit: string;
  subUnit: string;
  detailUnit: string;
  difficulty: Difficulty;
  problemType: ProblemType;
  answerType: AnswerType;
}

import React, { useState } from 'react';
import SelectionPanel from './components/SelectionPanel';
import ProblemDisplay from './components/ProblemDisplay';
import { generateMathProblem } from './services/geminiService';
import { SelectionState, GeneratedProblem, SchoolLevel, Difficulty, ProblemType, AnswerType } from './types';

// Default initial state matching new 2022 curriculum constants
const INITIAL_SELECTION: SelectionState = {
  schoolLevel: SchoolLevel.HIGH,
  grade: '공통수학1',
  mainUnit: '다항식',
  subUnit: '다항식의 연산',
  detailUnit: '다항식의 덧셈과 뺄셈',
  difficulty: Difficulty.MEDIUM,
  problemType: ProblemType.TYPE,
  answerType: AnswerType.MULTIPLE_CHOICE
};

const App: React.FC = () => {
  const [selection, setSelection] = useState<SelectionState>(INITIAL_SELECTION);
  const [problem, setProblem] = useState<GeneratedProblem | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleGenerate = async () => {
    setIsLoading(true);
    setError(null);
    try {
      const generated = await generateMathProblem(selection);
      setProblem(generated);
    } catch (err: any) {
      console.error(err);
      setError("문제를 생성하는 도중 오류가 발생했습니다. 잠시 후 다시 시도해주세요.");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex h-screen w-full bg-slate-100 font-sans text-slate-900 print:h-auto print:bg-white print:block">
      {/* Container - flex on screen, block on print */}
      <div className="flex w-full h-full overflow-hidden print:h-auto print:overflow-visible print:block">

        {/* Left Panel: Settings - Hidden on Print */}
        <SelectionPanel 
          selection={selection} 
          onChange={setSelection}
          onGenerate={handleGenerate}
          isLoading={isLoading}
        />

        {/* Right Panel: Display - Full width on Print */}
        <div className="flex-1 flex flex-col h-full relative print:h-auto print:w-full print:block">
          {error && (
            <div className="absolute top-4 left-1/2 transform -translate-x-1/2 bg-red-100 border border-red-200 text-red-700 px-4 py-2 rounded-lg shadow-lg z-50 flex items-center gap-2 print:hidden">
              <span className="font-bold">오류!</span> {error}
            </div>
          )}

          <ProblemDisplay problem={problem} isLoading={isLoading} />
        </div>
      </div>
    </div>
  );
};

export default App;

import React, { useEffect, useState } from 'react';
import { SelectionState, SchoolLevel, Difficulty, ProblemType, AnswerType, CurriculumUnit } from '../types';
import { MIDDLE_SCHOOL_CURRICULUM, HIGH_SCHOOL_CURRICULUM } from '../constants';
import { BookOpen, GraduationCap, Layers, Zap, PenTool } from 'lucide-react';

interface SelectionPanelProps {
  selection: SelectionState;
  onChange: (newSelection: SelectionState) => void;
  onGenerate: () => void;
  isLoading: boolean;
}

const SelectionPanel: React.FC<SelectionPanelProps> = ({ selection, onChange, onGenerate, isLoading }) => {
  const [availableMainUnits, setAvailableMainUnits] = useState<CurriculumUnit[]>([]);
  const [availableSubUnits, setAvailableSubUnits] = useState<CurriculumUnit[]>([]);
  const [availableDetailUnits, setAvailableDetailUnits] = useState<CurriculumUnit[]>([]);

  // Update Main Units when Level/Grade changes
  useEffect(() => {
    let units: CurriculumUnit[] = [];
    if (selection.schoolLevel === SchoolLevel.MIDDLE) {
      units = MIDDLE_SCHOOL_CURRICULUM[selection.grade] || [];
    } else {
      units = HIGH_SCHOOL_CURRICULUM[selection.grade] || [];
    }
    setAvailableMainUnits(units);

    // Reset downward selections safely
    if (units.length > 0) {
      handleChange('mainUnit', units[0].name);
    } else {
      handleChange('mainUnit', '');
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selection.schoolLevel, selection.grade]);

  // Update Sub Units when Main Unit changes
  useEffect(() => {
    const main = availableMainUnits.find(u => u.name === selection.mainUnit);
    const subs = main?.subUnits || [];
    setAvailableSubUnits(subs);

    if (subs.length > 0) {
      handleChange('subUnit', subs[0].name);
    } else {
      handleChange('subUnit', '');
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selection.mainUnit, availableMainUnits]);

  // Update Detail Units when Sub Unit changes
  useEffect(() => {
    const sub = availableSubUnits.find(u => u.name === selection.subUnit);
    const details = sub?.subUnits || [];
    setAvailableDetailUnits(details);

    if (details.length > 0) {
      handleChange('detailUnit', details[0].name);
    } else {
      handleChange('detailUnit', '');
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selection.subUnit, availableSubUnits]);

  const handleChange = (field: keyof SelectionState, value: any) => {
    if (selection[field] !== value) {
      onChange({ ...selection, [field]: value });
    }
  };

  const getGrades = () => {
    return selection.schoolLevel === SchoolLevel.MIDDLE 
      ? ['1학년 1학기', '1학년 2학기', '2학년 1학기', '2학년 2학기', '3학년 1학기', '3학년 2학기'] 
      : ['공통수학1', '공통수학2', '대수', '미적분I', '확률과 통계', '미적분II', '기하'];
  };

  return (
    <div className="w-full md:w-80 bg-white border-r border-slate-200 h-full flex flex-col print:hidden">
      <div className="p-6 border-b border-slate-100">
        <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
          <GraduationCap className="text-indigo-600" />
          MathGen AI
        </h1>
        <p className="text-xs text-slate-500 mt-1">2022 개정 교육과정 기반</p>
      </div>

      <div className="flex-1 overflow-y-auto p-6 space-y-6">

        {/* School Level & Grade */}
        <div className="space-y-3">
          <label className="text-sm font-semibold text-slate-700 flex items-center gap-2">
            <BookOpen size={16} /> 학제 및 학년
          </label>
          <div className="grid grid-cols-2 gap-2">
            {(Object.values(SchoolLevel) as string[]).map((level) => (
              <button
                key={level}
                onClick={() => handleChange('schoolLevel', level)}
                className={`px-3 py-2 text-sm rounded-lg transition-colors border ${
                  selection.schoolLevel === level
                    ? 'bg-indigo-50 border-indigo-200 text-indigo-700 font-medium'
                    : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'
                }`}
              >
                {level}
              </button>
            ))}
          </div>
          <select
            value={selection.grade}
            onChange={(e) => handleChange('grade', e.target.value)}
            className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
          >
            {getGrades().map(g => <option key={g} value={g}>{g}</option>)}
          </select>
        </div>

        {/* Units */}
        <div className="space-y-3">
          <label className="text-sm font-semibold text-slate-700 flex items-center gap-2">
            <Layers size={16} /> 단원 선택
          </label>
          <div className="space-y-2">
            <div>
              <span className="text-xs text-slate-500 mb-1 block">대단원</span>
              <select
                value={selection.mainUnit}
                onChange={(e) => handleChange('mainUnit', e.target.value)}
                className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-lg text-sm outline-none focus:border-indigo-500 transition-colors"
              >
                {availableMainUnits.length > 0 ? (
                  availableMainUnits.map(u => <option key={u.name} value={u.name}>{u.name}</option>)
                ) : (
                  <option value="">단원 없음</option>
                )}
              </select>
            </div>
            <div>
              <span className="text-xs text-slate-500 mb-1 block">중단원</span>
              <select
                value={selection.subUnit}
                onChange={(e) => handleChange('subUnit', e.target.value)}
                className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-lg text-sm outline-none focus:border-indigo-500 transition-colors"
                disabled={availableSubUnits.length === 0}
              >
                {availableSubUnits.length > 0 ? (
                   availableSubUnits.map(u => <option key={u.name} value={u.name}>{u.name}</option>)
                ) : (
                  <option value="">중단원 없음</option>
                )}
              </select>
            </div>
            <div>
              <span className="text-xs text-slate-500 mb-1 block">소단원</span>
               {availableDetailUnits.length > 0 ? (
                <select 
                  value={selection.detailUnit}
                  onChange={(e) => handleChange('detailUnit', e.target.value)}
                  className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-lg text-sm outline-none focus:ring-2 focus:ring-indigo-500"
                >
                  {availableDetailUnits.map(u => <option key={u.name} value={u.name}>{u.name}</option>)}
                </select>
              ) : (
                <input 
                  type="text"
                  value={selection.detailUnit}
                  onChange={(e) => handleChange('detailUnit', e.target.value)}
                  placeholder="직접 입력"
                  className="w-full p-2.5 bg-white border border-slate-200 rounded-lg text-sm outline-none focus:ring-2 focus:ring-indigo-500"
                />
              )}
            </div>
          </div>
        </div>

        {/* Difficulty, Type, Format */}
        <div className="space-y-3">
          <label className="text-sm font-semibold text-slate-700 flex items-center gap-2">
            <Zap size={16} /> 난이도 및 유형
          </label>
          <div className="space-y-2">
            <div className="grid grid-cols-2 gap-2">
              <select
                value={selection.difficulty}
                onChange={(e) => handleChange('difficulty', e.target.value)}
                className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-lg text-sm outline-none"
              >
                {Object.values(Difficulty).map(d => <option key={d} value={d}>{d}</option>)}
              </select>
              <select
                value={selection.problemType}
                onChange={(e) => handleChange('problemType', e.target.value)}
                className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-lg text-sm outline-none"
              >
                {Object.values(ProblemType).map(t => <option key={t} value={t}>{t}</option>)}
              </select>
            </div>

            {/* Answer Type (Objective vs Subjective) */}
            <div className="flex bg-slate-50 p-1 rounded-lg border border-slate-200">
               {Object.values(AnswerType).map((type) => (
                 <button
                   key={type}
                   onClick={() => handleChange('answerType', type)}
                   className={`flex-1 py-2 text-sm font-medium rounded-md transition-all ${
                     selection.answerType === type
                       ? 'bg-white text-indigo-700 shadow-sm border border-slate-100'
                       : 'text-slate-500 hover:text-slate-700'
                   }`}
                 >
                   {type === AnswerType.MULTIPLE_CHOICE ? '객관식' : '주관식'}
                 </button>
               ))}
            </div>
            <p className="text-xs text-slate-400 text-center">
              {selection.answerType === AnswerType.MULTIPLE_CHOICE 
                ? '5지선다형 문제가 생성됩니다.' 
                : '풀이 과정이 중요한 서술형 문제가 생성됩니다.'}
            </p>
          </div>
        </div>
      </div>

      <div className="p-6 border-t border-slate-200 bg-slate-50">
        <button
          onClick={onGenerate}
          disabled={isLoading || !selection.mainUnit}
          className={`w-full py-3.5 rounded-xl text-white font-bold shadow-lg shadow-indigo-200 flex items-center justify-center gap-2 transition-all ${
            isLoading || !selection.mainUnit
              ? 'bg-indigo-300 cursor-not-allowed'
              : 'bg-indigo-600 hover:bg-indigo-700 hover:shadow-indigo-300 active:scale-95'
          }`}
        >
          {isLoading ? (
            <>
              <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
              생성 중...
            </>
          ) : (
            <>
              <PenTool size={20} fill="currentColor" />
              문제 생성하기
            </>
          )}
        </button>
      </div>
    </div>
  );
};

export default SelectionPanel;

import { GoogleGenAI, Type } from "@google/genai";
import { GeneratedProblem, SelectionState, AnswerType } from "../types";

// Initialize Gemini Client
const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key is missing. Please set process.env.API_KEY.");
  }
  return new GoogleGenAI({ apiKey });
};

export const generateMathProblem = async (selection: SelectionState): Promise<GeneratedProblem> => {
  const ai = getClient();

  // Construct the prompt context based on user selection
  const topicPath = `${selection.schoolLevel} ${selection.grade} > ${selection.mainUnit} > ${selection.subUnit} > ${selection.detailUnit}`;

  const prompt = `
    You are an expert Mathematics Teacher in South Korea, specializing in the "2022 Revised National Curriculum" (2022 개정 교육과정).

    Task: Create a mathematics problem based on the following specifications.

    Target Audience/Topic:
    - Curriculum Path: ${topicPath}
    - Difficulty: ${selection.difficulty} (Range: Lower, Middle, High, Highest)
    - Problem Goal: ${selection.problemType}
    - Question Format: ${selection.answerType}

    Requirements:
    1. The problem must be mathematically accurate and suitable for the selected grade level in Korea.
    2. [Text Formatting & LaTeX - CRITICAL]
       - Use LaTeX formatting for **ALL** mathematical expressions, numbers, variables, and formulas.
       - **Inline Math**: Wrap in single dollar signs, e.g., $x^2 + 2x + 1$.
       - **Block Math**: Wrap in double dollar signs, e.g., $$ \\frac{-b \\pm \\sqrt{b^2 - 4ac}}{2a} $$.
       - **CHOICES (보기)**: You MUST wrap the mathematical content of each choice in $ symbols. 
         - Incorrect: "x^2 + x" 
         - Correct: "$x^2 + x$"
       - AVOID complex LaTeX table environments inside the "question" text. Use standard Markdown tables.

    3. [Question Format Rules - CRITICAL]
       - **If Question Format is '객관식 (5지선다)'**:
         - You MUST provide exactly 5 choices in the "choices" array.
         - The answer must be one of these choices.
       - **If Question Format is '주관식/서술형'**:
         - The "choices" array MUST be empty [].
         - The question should invite a calculation or detailed explanation.

    4. [Visuals & Diagrams]
       - If the problem involves **Geometry**, **Graphs**, or **Statistics** (Stem & Leaf, etc.):
         - Generate a valid, high-quality **SVG string** in the "diagramSVG" field.
         - Self-contained SVG with 'viewBox', black strokes, transparent background.
       - Otherwise, set "diagramSVG" to null.

    5. [Solution Quality - WORKBOOK STYLE]
       - Provide a professional, detailed solution similar to famous Korean workbooks (like Ssen, Black Label).
       - **Structure**:
         - **[Step 1]**: Initial approach or formula setup.
         - **[Step 2]**: Calculation or logical deduction.
