              description: "SVG code or null.",
              nullable: true
            }
          },
          required: ["question", "answer", "solution", "topic", "difficulty"]
        }
      }
    });

    if (!response.text) {
      throw new Error("No content generated.");
    }

    let jsonString = response.text.trim();
    if (jsonString.startsWith('```json')) {
        jsonString = jsonString.replace(/^```json\s*/, '').replace(/\s*```$/, '');
    } else if (jsonString.startsWith('```')) {
        jsonString = jsonString.replace(/^```\s*/, '').replace(/\s*```$/, '');
    }

    const data = JSON.parse(jsonString) as GeneratedProblem;
    return data;
  } catch (error) {
    console.error("Error generating problem:", error);
    throw error;
  }
};

import React, { useState } from 'react';
import { GeneratedProblem } from '../types';
import MarkdownRenderer from './MarkdownRenderer';
import { Eye, EyeOff, CheckCircle, HelpCircle, FileText, Image as ImageIcon, Printer } from 'lucide-react';

interface ProblemDisplayProps {
  problem: GeneratedProblem | null;
  isLoading: boolean;
}

const ProblemDisplay: React.FC<ProblemDisplayProps> = ({ problem, isLoading }) => {
  const [showSolution, setShowSolution] = useState(false);

  // Reset show solution when problem changes
  React.useEffect(() => {
    setShowSolution(false);
  }, [problem]);

  // Handler for printing
  const handlePrint = (mode: 'problem' | 'solution') => {
    // Determine visibility based on mode
    if (mode === 'problem') {
      setShowSolution(false);
    } else {
      setShowSolution(true);
    }
    // Timeout to allow state update and re-render before printing
    setTimeout(() => {
      window.print();
    }, 100);
  };

  if (isLoading) {
    return (
      <div className="flex-1 flex flex-col items-center justify-center p-12 text-center h-full">
        <div className="w-16 h-16 mb-6 rounded-full border-4 border-indigo-100 border-t-indigo-600 animate-spin" />
        <h3 className="text-xl font-bold text-slate-800 mb-2">AI 선생님이 문제를 만들고 있어요</h3>
        <p className="text-slate-500 max-w-sm">
          선택하신 단원과 난이도를 분석하여 최적의 문제를 생성 중입니다. 잠시만 기다려주세요.
        </p>
      </div>
    );
  }

  if (!problem) {
    return (
      <div className="flex-1 flex flex-col items-center justify-center p-12 text-center bg-slate-50/50 h-full">
        <div className="w-20 h-20 bg-indigo-50 text-indigo-200 rounded-3xl flex items-center justify-center mb-6">
          <FileText size={40} />
        </div>
        <h3 className="text-xl font-bold text-slate-800 mb-2">문제를 생성해보세요</h3>
        <p className="text-slate-500 max-w-sm">
          왼쪽 패널에서 학년, 단원, 난이도를 선택하고 '문제 생성하기' 버튼을 눌러주세요.
        </p>
      </div>
    );
  }

  return (
    <div className="flex-1 overflow-y-auto bg-slate-100/50 p-4 md:p-8 print:p-0 print:bg-white print:overflow-visible">
      <div className="max-w-4xl mx-auto space-y-6 print:max-w-none print:space-y-4">

