import { GoogleGenAI, Type } from "@google/genai";
import { GeneratedProblem, SelectionState } from "../types";

// Initialize Gemini Client
const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key is missing. Please set process.env.API_KEY.");
  }
  return new GoogleGenAI({ apiKey });
};

// Common schema for both text and image modes
const RESPONSE_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    question: {
      type: Type.STRING,
      description: "The main text. Use Markdown. WRAP MATH IN $...$."
    },
    choices: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: "Array of 5 options. Leave EMPTY for subjective. WRAP MATH IN $...$."
    },
    answer: {
      type: Type.STRING,
      description: "The final answer. IF OBJECTIVE: Include number (e.g., '(3) ...'). IF SUBJECTIVE: Just the value."
    },
    solution: {
      type: Type.STRING,
      description: "Detailed step-by-step solution. MUST USE NEWLINES BETWEEN STEPS."
    },
    topic: {
      type: Type.STRING,
      description: "Topic label derived from image or selection."
    },
    difficulty: {
      type: Type.STRING,
      description: "Difficulty level."
    },
    diagramSVG: {
      type: Type.STRING,
      description: "SVG code or null.",
      nullable: true
    }
  },
  required: ["question", "answer", "solution", "topic", "difficulty"]
};

const buildTextPrompt = (selection: SelectionState): string => {
  const topicPath = `${selection.schoolLevel} ${selection.grade} > ${selection.mainUnit} > ${selection.subUnit} > ${selection.detailUnit}`;

  return `
    You are an expert Mathematics Teacher in South Korea, specializing in the "2022 Revised National Curriculum" (2022 개정 교육과정).

    Task: Create a mathematics problem based on the following specifications.

    Target Audience/Topic:
    - Curriculum Path: ${topicPath}
    - Difficulty: ${selection.difficulty} (Range: Lower, Middle, High, Highest)
    - Problem Goal: ${selection.problemType}
    - Question Format: ${selection.answerType}

    ${COMMON_INSTRUCTIONS}
  `;
};

const buildImagePrompt = (selection: SelectionState): string => {
  return `
    You are an expert Mathematics Teacher in South Korea.

    Task: Analyze the provided image of a math problem and generate a **NEW, SIMILAR** problem.

    1. **Analyze**: Identify the mathematical concept, topic, and difficulty level of the problem in the image.
    2. **Generate**: Create a **NEW** problem that tests the **same concept** and has a **similar difficulty**.
       - Do NOT just solve the problem in the image.
       - Do NOT copy the problem exactly. Change numbers, functions, or context while keeping the core logic similar.
    3. **Constraint Override**:
       - Target Difficulty: ${selection.difficulty} (Adjust the generated problem to match this difficulty if possible, otherwise stick to the image's level).
       - Question Format: ${selection.answerType} (Force the output to be this format).

    ${COMMON_INSTRUCTIONS}
  `;
};

const COMMON_INSTRUCTIONS = `
    Requirements:
    1. The problem must be mathematically accurate and suitable for Korean students.
    2. [Text Formatting & LaTeX - CRITICAL]
       - Use LaTeX formatting for **ALL** mathematical expressions, numbers, variables, and formulas.
       - **Inline Math**: Wrap in single dollar signs, e.g., $x^2 + 2x + 1$.
       - **Block Math**: Wrap in double dollar signs, e.g., $$ \\frac{-b \\pm \\sqrt{b^2 - 4ac}}{2a} $$.
       - **CHOICES (보기)**: You MUST wrap the mathematical content of each choice in $ symbols. 
         - Incorrect: "x^2 + x" 
         - Correct: "$x^2 + x$"
       - AVOID complex LaTeX table environments inside the "question" text. Use standard Markdown tables.

    3. [Question Format Rules - CRITICAL]
       - **If Question Format is '객관식 (5지선다)'**:
         - You MUST provide exactly 5 choices in the "choices" array.
         - The answer must be one of these choices.
       - **If Question Format is '주관식/서술형'**:
         - The "choices" array MUST be empty [].
         - The question should invite a calculation or detailed explanation.

    4. [Visuals & Diagrams - HIGH QUALITY REQUIRED]
       - **When to generate**: If the topic involves **Geometry** (Plane/Solid), **Functions** (Graphs), or **Statistics** (Charts/Histograms).
       - **SVG Requirements**:
         - **Code**: Provide raw, valid SVG string in "diagramSVG".
         - **Style**: 
           - **ViewBox**: Appropriately sized (e.g., "0 0 300 250").
           - **Stroke**: Black (#000). Main object lines: width **2px**. Axes/Auxiliary lines: width **1px**.
           - **Text**: Sans-serif, size **>= 14px**. Ensure labels (A, B, x, y, O) are clearly visible and not overlapping.
           - **Background**: Transparent.
         - **Specific Scenarios**:
           - **Geometry**: Label vertices (A, B, C) clearly. Mark right angles (square symbol) or equal lengths (tick marks) if stated.
           - **Functions**: Draw X/Y axes with arrows. Mark origin O. Draw the curve smoothly. Label key points.
           - **Statistics (Torn Graphs)**: If the problem describes a "torn" or "stained" part of a graph (e.g., broken line graph, histogram), explicitly draw the visible parts and use **jagged lines** or a **dashed outline** to represent the missing/torn area visually.
       - If NO diagram is needed (e.g., pure calculation), set "diagramSVG" to null.

    5. [Solution Quality - WORKBOOK STYLE]
       - Provide a professional, detailed solution similar to famous Korean workbooks (like Ssen, Black Label).
       - **Structure**:
         - Use clear headers for each step, e.g., **[1단계: ...]**, **[2단계: ...]**, **[3단계: ...]**.
       - **Formatting (CRITICAL)**:
         - **You MUST insert a blank line (double newline \\n\\n) BEFORE starting a new step or header.**
         - Ensure the text is NOT one large block. Visually separate each logical step.
         - Example:
           **[1단계: 식 세우기]**
           (Explanation...)

           **[2단계: 계산하기]**
           (Explanation...)
       - **For Subjective Questions**: Include "채점 기준" (Grading Criteria) if applicable.
       - **Answer Field**: 
         - **If Multiple Choice**: MUST start with the choice number in parentheses or circled number, followed by the value (e.g., "(3) 5" or "③ 5").
         - **If Subjective**: Strictly contain the final result (e.g., "5", "$4\\pi$", "x=2"). Do not include the full sentence "The answer is...".

    6. The output MUST be valid JSON.

    Language: Korean (한국어)
`;

export const generateMathProblem = async (selection: SelectionState): Promise<GeneratedProblem> => {
  const ai = getClient();
  let contents: any;

  if (selection.mode === 'image' && selection.sourceImage) {
    // Image Mode
    const base64Data = selection.sourceImage.split(',')[1];
    // Simple MIME type detection based on header, default to jpeg if missing but reader usually provides it.
    // The reader format is "data:image/png;base64,..."
    const mimeMatch = selection.sourceImage.match(/data:([a-zA-Z0-9]+\/[a-zA-Z0-9-.+]+).*,.*/);
    const mimeType = mimeMatch ? mimeMatch[1] : 'image/jpeg';

    contents = {
      parts: [
        {
          inlineData: {
            mimeType: mimeType,
            data: base64Data
          }
        },
        { text: buildImagePrompt(selection) }
      ]
    };
  } else {
    // Text Mode
    contents = buildTextPrompt(selection);
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview', 
      contents: contents,
      config: {
        responseMimeType: "application/json",
        responseSchema: RESPONSE_SCHEMA
      }
    });

    if (!response.text) {
      throw new Error("No content generated.");
    }

    let jsonString = response.text.trim();
    if (jsonString.startsWith('```json')) {
        jsonString = jsonString.replace(/^```json\s*/, '').replace(/\s*```$/, '');
    } else if (jsonString.startsWith('```')) {
        jsonString = jsonString.replace(/^```\s*/, '').replace(/\s*```$/, '');
    }

    const data = JSON.parse(jsonString) as GeneratedProblem;
    return data;
  } catch (error) {
    console.error("Error generating problem:", error);
    throw error;
  }
};

import React, { useEffect, useState, useRef } from 'react';
import { SelectionState, SchoolLevel, Difficulty, ProblemType, AnswerType, CurriculumUnit } from '../types';
import { MIDDLE_SCHOOL_CURRICULUM, HIGH_SCHOOL_CURRICULUM, ELEMENTARY_SCHOOL_CURRICULUM } from '../constants';
import { BookOpen, GraduationCap, Layers, Zap, PenTool, Image as ImageIcon, Upload, X } from 'lucide-react';

interface SelectionPanelProps {
  selection: SelectionState;
  onChange: (newSelection: SelectionState) => void;
  onGenerate: () => void;
  isLoading: boolean;
}

const SelectionPanel: React.FC<SelectionPanelProps> = ({ selection, onChange, onGenerate, isLoading }) => {
  const [availableMainUnits, setAvailableMainUnits] = useState<CurriculumUnit[]>([]);
  const [availableSubUnits, setAvailableSubUnits] = useState<CurriculumUnit[]>([]);
  const [availableDetailUnits, setAvailableDetailUnits] = useState<CurriculumUnit[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Update Main Units when Level/Grade changes
  useEffect(() => {
    let units: CurriculumUnit[] = [];
    if (selection.schoolLevel === SchoolLevel.ELEMENTARY) {
      units = ELEMENTARY_SCHOOL_CURRICULUM[selection.grade] || [];
    } else if (selection.schoolLevel === SchoolLevel.MIDDLE) {
      units = MIDDLE_SCHOOL_CURRICULUM[selection.grade] || [];
    } else {
      units = HIGH_SCHOOL_CURRICULUM[selection.grade] || [];
    }
    setAvailableMainUnits(units);

    // Reset downward selections safely only if we are in curriculum mode or initializing
    if (selection.mode === 'curriculum') {
       if (units.length > 0) {
        // Only reset if current selection is invalid for new grade
        const currentValid = units.some(u => u.name === selection.mainUnit);
        if (!currentValid) handleChange('mainUnit', units[0].name);
      } else {
        handleChange('mainUnit', '');
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selection.schoolLevel, selection.grade]);

  // Update Sub Units when Main Unit changes
  useEffect(() => {
    const main = availableMainUnits.find(u => u.name === selection.mainUnit);
    const subs = main?.subUnits || [];
    setAvailableSubUnits(subs);

    if (selection.mode === 'curriculum') {
      if (subs.length > 0) {
         const currentValid = subs.some(u => u.name === selection.subUnit);
         if (!currentValid) handleChange('subUnit', subs[0].name);
      } else {
        handleChange('subUnit', '');
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selection.mainUnit, availableMainUnits]);

  // Update Detail Units when Sub Unit changes
  useEffect(() => {
    const sub = availableSubUnits.find(u => u.name === selection.subUnit);
    const details = sub?.subUnits || [];
    setAvailableDetailUnits(details);

    if (selection.mode === 'curriculum') {
      if (details.length > 0) {
        const currentValid = details.some(u => u.name === selection.detailUnit);
        if (!currentValid) handleChange('detailUnit', details[0].name);
      } else {
        handleChange('detailUnit', '');
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selection.subUnit, availableSubUnits]);

  // Handle Ctrl+V Paste for Images
  useEffect(() => {
    const handlePaste = (e: ClipboardEvent) => {
      // Only active in Image Mode
      if (selection.mode !== 'image') return;

      const items = e.clipboardData?.items;
      if (!items) return;

      for (let i = 0; i < items.length; i++) {
        if (items[i].type.indexOf('image') !== -1) {
          const file = items[i].getAsFile();
          if (file) {
            e.preventDefault(); // Prevent default paste behavior
            const reader = new FileReader();
            reader.onloadend = () => {
              // Update state directly using the prop function to avoid closure staleness if needed,
              // though here we use the wrapper which calls onChange with current selection spread.
              // We need to be careful about `selection` dependency.
              // Ideally, we construct the new state.
              onChange({ ...selection, sourceImage: reader.result as string });
            };
            reader.readAsDataURL(file);
            return; // Stop after finding the first image
          }
        }
      }
    };

    window.addEventListener('paste', handlePaste);
    return () => {
      window.removeEventListener('paste', handlePaste);
    };
  }, [selection.mode, selection, onChange]); 

  const handleChange = (field: keyof SelectionState, value: any) => {
    if (selection[field] !== value) {
      onChange({ ...selection, [field]: value });
    }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        handleChange('sourceImage', reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    const file = e.dataTransfer.files?.[0];
    if (file && file.type.startsWith('image/')) {
      const reader = new FileReader();
